initScript:
window.choHanInProgress = false;
window.choHanPlay = function(guess) {
  if (window.choHanInProgress) return;
  const BET = 50;
  const resEl = document.getElementById('chohan-res');
  if (state.points < BET) { resEl.innerText = 'Insufficient points (Min bet: ' + BET + ' pts)!'; return; }
  window.choHanInProgress = true;
  state.points -= BET; updatePointsDisplay();
  const cup = document.getElementById('chohan-cup');
  resEl.innerText = 'The dealer is shaking the cup... 🎲';
  cup.classList.add('animate-bounce');
  setTimeout(function() {
    cup.classList.remove('animate-bounce');
    const d1 = Math.floor(Math.random() * 6) + 1;
    const d2 = Math.floor(Math.random() * 6) + 1;
    const sum = d1 + d2;
    const resultIsEven = sum % 2 === 0;
    const won = (guess === 'cho') === resultIsEven;
    document.getElementById('chohan-dice-preview').innerHTML = '<span class="text-lg font-black tracking-widest">[' + d1 + '] [' + d2 + ']</span>';
    const label = resultIsEven ? '<span class="text-red-400">CHO/EVEN</span>' : '<span class="text-blue-400">HAN/ODD</span>';
    const outcome = won ? '<span class="text-emerald-400">You won ' + (BET * 2) + ' pts!</span>' : '<span class="text-red-400">House wins!</span>';
    if (won) state.points += BET * 2;
    resEl.innerHTML = 'Cup lifted! Rolled <span class="text-amber-400 font-extrabold">' + d1 + '</span> and <span class="text-amber-400 font-extrabold">' + d2 + '</span> (Sum: <span class="text-white">' + sum + '</span> - ' + label + '). ' + outcome;
    updatePointsDisplay();
    window.choHanInProgress = false;
  }, 1200);
};
